const tabId = 2017691837;
const saieDetails = await browserjs(tabId, () => {
  const detailsBtn = Array.from(document.querySelectorAll('button, summary, [role="tab"]')).find(b => b.innerText.includes("DETAILS"));
  if (detailsBtn) detailsBtn.click();
  const desc = document.querySelector('[id*="details"], [class*="details"], .product-description')?.innerText;
  const shadeList = Array.from(document.querySelectorAll('[data-shade-name], [aria-label*="shade"], [class*="swatch"], [class*="shade"]')).map(el => el.getAttribute('data-shade-name') || el.getAttribute('aria-label') || el.innerText);
  const text = document.body.innerText;
  const shades = ["Rosy", "Baby", "Chilly", "Poppy", "Spicy", "Dreamy", "Peachy", "Cutie", "Sweetie", "Lady"];
  const foundShades = shades.map(s => {
    const idx = text.indexOf(s);
    return idx !== -1 ? text.slice(idx, idx + 40).replace(/\n+/g, ' ') : null;
  }).filter(Boolean);
  return { desc, foundShades, shadeList: Array.from(new Set(shadeList)).slice(0, 15) };
});
console.log("Saie details:", JSON.stringify(saieDetails, null, 2));

