const tabId = 2017691837;
await tool.navigate({ tabId, url: "https://fentybeauty.com/products/cheeks-out-freestyle-cream-blush-petal-poppin" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

const fentyData = await browserjs(tabId, () => {
  return {
    title: document.title,
    h1: document.querySelector('h1')?.innerText?.trim(),
    price: document.querySelector('.price, [class*="price"]')?.innerText?.trim(),
    desc: document.querySelector('[class*="description"], [class*="product-details"]')?.innerText?.slice(0, 1500),
    bodySnippet: document.body.innerText.slice(0, 3000)
  };
});
console.log("Fenty details:", JSON.stringify(fentyData, null, 2));

