const tabId = 2017691837;
await tool.navigate({ tabId, url: "https://duckduckgo.com/html/?q=best+long+lasting+blush+all-day+wear+byrdie+allure" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

const links = await browserjs(tabId, () => {
  return Array.from(document.querySelectorAll('.result__title a'))
    .map(a => ({ text: a.textContent.trim(), href: a.href }))
    .filter(a => a.href.includes('byrdie.com') || a.href.includes('allure.com') || a.href.includes('cosmopolitan.com') || a.href.includes('vogue.com'));
});
console.log("Comparison/review links:", JSON.stringify(links.slice(0, 10), null, 2));

