const byrdie1 = await browserjs(tabId, () => {
  return {
    title: document.title,
    h1: document.querySelector('h1')?.innerText?.trim(),
    blushesMentioned: Array.from(document.querySelectorAll('h2, h3, [class*="heading"]'))
